gcode_macro CANCEL_PRINT.gcode:
STOP_LED_EFFECTS
SET_LED_EFFECT EFFECT=panel_idle
{% set idle_timeout = printer.configfile.settings.idle_timeout.timeout %}
SET_IDLE_TIMEOUT TIMEOUT={idle_timeout}
SET_HEATER_TEMPERATURE HEATER="the_filter" TARGET=0
DISABLE_STEPPER_FOLLOWER

{% set macro_found = True if printer['gcode_macro _CLIENT_VARIABLE'] is defined else False %}
{% set client = printer['gcode_macro _CLIENT_VARIABLE'] %}
{% set allow_park = False if not macro_found
else False if client.park_at_cancel is not defined
else True  if client.park_at_cancel|lower == 'true'
else False %}
{% set retract    = 5.0  if not macro_found else client.cancel_retract|default(5.0)|abs %}
{% set sp_retract = 2100 if not macro_found else client.speed_retract|default(35) * 60 %}

{% if not printer.pause_resume.is_paused and allow_park %} _TOOLHEAD_PARK_PAUSE_CANCEL {% endif %}
{% if printer.extruder.can_extrude %}
M83
G1 E-{retract} F{sp_retract}
{% if printer.gcode_move.absolute_extrude %} M82 {% endif %}
{% else %}
{action_respond_info("Extruder not hot enough")}
{% endif %}
SET_HEATER_TEMPERATURE HEATER=extruder
M106 S0
CANCEL_PRINT_BASE


STOP_LED_EFFECTS
SET_LED_EFFECT EFFECT=panel_idle REPLACE=1
SET_LED_EFFECT EFFECT=progress_bar_idle REPLACE=1

OAMS_LOADED
M117 Ready
STATUS_READY

gcode_macro CLEAN_NOZZLE.gcode:
{% if "xyz" not in printer.toolhead.homed_axes %}
G28
{% endif %}

G90


G1 X{start_x} Y{start_y} F6000





{% for wipes in range(1, (wipe_qty + 1)) %}
G1 X{start_x + wipe_dist} F{wipe_spd * 60}
G1 X{start_x} F{wipe_spd * 60}
{% endfor %}

gcode_macro CUT_FILAMENT.gcode:
{% set v = printer["gcode_macro _oams_macro_variables"] %}
{% if printer.toolhead.homed_axes != 'xyz' %}
RESPOND TYPE=command MSG='Homing'
G28
{% endif %}
RESPOND TYPE=command MSG='Cutting'


G90
G0 X{v.pre_cut_x} Y{v.pre_cut_y} F{v.pre_cut_speed}
G0 X{v.cut_x} Y{v.cut_y} F{v.cut_speed}
G0 X{v.post_cut_x} Y{v.post_cut_y} F{v.pre_cut_speed}
M400

gcode_macro CYCLE_CHAMBER_LIGHTS.gcode:
{% if state == "on" %}
SET_LED_EFFECT EFFECT=panel_idle REPLACE=1
SET_GCODE_VARIABLE MACRO=CYCLE_CHAMBER_LIGHTS VARIABLE=state VALUE='"idle"'
{% elif state == "idle" %}
SET_LED_EFFECT EFFECT=panel_off REPLACE=1
SET_GCODE_VARIABLE MACRO=CYCLE_CHAMBER_LIGHTS VARIABLE=state VALUE='"off"'
{% else %}
SET_LED_EFFECT EFFECT=panel_on REPLACE=1
SET_GCODE_VARIABLE MACRO=CYCLE_CHAMBER_LIGHTS VARIABLE=state VALUE='"on"'
{% endif %}

gcode_macro EXTRUDE_VOLUMETRIC.gcode:
{% set D = params.D|float %}
{% set EXTRUDER = params.EXTRUDER|default("extruder") %}
{% set VOLUME = params.VOLUME|float %}
{% set SPEED = params.SPEED|float %}


{% if D <= 0 %}
respond_error "Invalid filament diameter: D must be greater than 0"
return
{% endif %}
{% if VOLUME <= 0 %}
respond_error "Invalid volume: VOLUME must be greater than 0"
return
{% endif %}
{% if SPEED <= 0 %}
respond_error "Invalid speed: SPEED must be greater than 0"
return
{% endif %}


{% set area = (3.14159 * (D / 2) ** 2) %}


{% set length = VOLUME / area %}


respond_info "Extruding length of filament: {length} mm at speed { SPEED } mm/min with filament diameter {D } mm"


ACTIVATE_EXTRUDER EXTRUDER={EXTRUDER}
G1 E{length} F{SPEED}

gcode_macro G28.gcode:
{% set home_all = 'X' not in params and 'Y' not in params and 'Z' not in params %}

{% if 'z' not in printer.toolhead.homed_axes %}
UNSAFE_LIFT_TOOLHEAD
{% endif %}

{% if home_all or 'X' in params %}
_HOME_X
{% endif %}

{% if home_all or 'Y' in params %}
_HOME_Y
{% endif %}

{% if home_all or 'Z' in params %}
G28.1 Z
G0 Z10
{% endif %}

gcode_macro GREASE_RAILS.gcode:
{% if "xyz" not in printer.toolhead.homed_axes %}
G28
{% endif %}
G90

G0 X{x_width / 2} Y{y_width / 2} F6000
G0 Z{safe_z_height} F{speed}

{% for travels in range(0, repeat_times) %}
G0 X0
G0 X{x_width}
{% endfor %}
G0 X{x_width / 2}

{% for travels in range(0, repeat_times) %}
G0 Y0
G0 Y{y_width}
{% endfor %}
G0 Y{y_width / 2}

{% for travels in range(0, repeat_times) %}
G0 Z{z_height} F{z_speed}
G0 Z{safe_z_height}
{% endfor %}

gcode_macro OAMS_TOOLCHANGE_TORTURE_TEST.gcode:
{% set num = params.LOOPS|int %}
G0 Z{extrusion_z_height} F30
{% for i in range(num) %}
{% for j in range(4) %}
T{j}
RESPOND TYPE=command MSG='Purging {extrusion_amount}mm of filament'
{% endfor %}
RESPOND TYPE=command MSG='Number of loops now {i+1}'
{% endfor %}

gcode_macro OAMS_TORTURE_TEST.gcode:
{% set num = params.LOOPS|int %}
{% for i in range(num) %}
{% for j in range(4) %}
OAMS_LOAD_SPOOL OAMS=1 SPOOL={j}
OAMS_UNLOAD_SPOOL OAMS=1
{% endfor %}
RESPOND TYPE=command MSG='Number of loops now {i+1}'
{% endfor %}

gcode_macro OPENAMS_LOAD.gcode:
{% if 'GROUP' not in params %}
{ action_raise_error("OPENAMS_LOAD requires GROUP") }
{% elif 'SLOT' not in params %}
{ action_raise_error("OPENAMS_LOAD requires SLOT") }
{% else %}
_TX GROUP={params.GROUP} SLOT={params.SLOT}
{% endif %}

gcode_macro OPENAMS_UNLOAD.gcode:
{% set manager = printer['oams_manager'] %}
{% set ns = namespace(lane=params.FPS|default(none)) %}
{% if ns.lane is none %}{% for name in manager.lanes_by_fps %}{% if manager.lanes_by_fps[name].extruder == printer.toolhead.extruder %}{% set ns.lane = name %}{% endif %}{% endfor %}{% endif %}
{% if ns.lane is none and manager.lanes_by_fps|length == 1 %}{% set ns.lane = (manager.lanes_by_fps|list)[0] %}{% endif %}
{% if ns.lane is none %}
{ action_raise_error("Cannot tell which OpenAMS lane to unload; pass FPS=<name>") }
{% endif %}
{% set LANE = ns.lane %}
{% if manager.lanes_by_fps[LANE].current_slot is not none %}
SAFE_UNLOAD_FILAMENT STRICT=1 FPS={LANE}
{% else %}
RESPOND TYPE=command MSG='OpenAMS is already unloaded'
{% endif %}

gcode_macro PRINT_START.gcode:
SET_LED_EFFECT EFFECT=panel_on REPLACE=1
STATUS_BUSY

M140 S{ params.BED }
M190 S{ params.BED }

{% set axes_homed  = 'xyz' in printer.toolhead.homed_axes %}
{% set mesh_loaded = printer.bed_mesh.profile_name != '' %}

{% if axes_homed and mesh_loaded %}

M117 Skipping calibration
SET_GCODE_OFFSET Z=0

M104 S{ params.EXTRUDER }
M109 S{ params.EXTRUDER }

SET_GCODE_OFFSET Z=0.030 MOVE=1
{% else %}

BED_MESH_CLEAR
SET_GCODE_OFFSET Z=0

G28
G0 Z4

M109 S150
G4 P20000

CLEAN_NOZZLE

QUAD_GANTRY_LEVEL

G28.1 Z METHOD=CONTACT CALIBRATE=1

BED_MESH_CALIBRATE PROFILE="default"
BED_MESH_PROFILE LOAD=default

M104 S{ params.EXTRUDER }
M109 S{ params.EXTRUDER }

SET_GCODE_OFFSET Z=0.030 MOVE=1
{% endif %}

STATUS_PRINTING
OAMSM_FOLLOWER FPS=fps1 ENABLE=1 DIRECTION=1

gcode_macro RESUME.gcode:
{% set idle_timeout = printer.configfile.settings.idle_timeout.timeout %}
SET_IDLE_TIMEOUT TIMEOUT={idle_timeout}

{% set macro_found = True if printer['gcode_macro _CLIENT_VARIABLE'] is defined else False %}
{% set client = printer['gcode_macro _CLIENT_VARIABLE'] %}
{% set velocity = printer.configfile.settings.pause_resume.recover_velocity %}
{% set use_fw_retract = False if not macro_found
else False if client.use_fw_retract is not defined
else True  if client.use_fw_retract|lower == 'true' and printer.firmware_retraction is defined
else False %}
{% set unretract    = 1.0  if not macro_found else client.unretract|default(1.0)|abs %}
{% set sp_unretract = 2100 if not macro_found else client.speed_unretract|default(35) * 60 %}
{% set sp_move      = velocity if not macro_found else client.speed_move|default(velocity) %}

{% if printer.extruder.can_extrude %}
{% if use_fw_retract %}
G11
{% else %}
M83
G1 E{unretract} F{sp_unretract}
{% if printer.gcode_move.absolute_extrude %} M82 {% endif %}
{% endif %}
{% else %}
{action_respond_info("Extruder not hot enough %s" % use_fw_retract)}
{% endif %}
M117 Printing
STATUS_PRINTING
RESUME_BASE VELOCITY={params.VELOCITY|default(sp_move)}

gcode_macro SAFE_UNLOAD_FILAMENT.gcode:
{% set v = printer["gcode_macro _oams_macro_variables"] %}
{% set manager = printer['oams_manager'] %}
{% set ns = namespace(lane=params.FPS|default(none)) %}
{% if ns.lane is none %}{% for name in manager.lanes_by_fps %}{% if manager.lanes_by_fps[name].extruder == printer.toolhead.extruder %}{% set ns.lane = name %}{% endif %}{% endfor %}{% endif %}
{% if ns.lane is none and manager.lanes_by_fps|length == 1 %}{% set ns.lane = (manager.lanes_by_fps|list)[0] %}{% endif %}
{% if ns.lane is none %}
{ action_raise_error("Cannot tell which OpenAMS lane to unload; pass FPS=<name>") }
{% endif %}
{% set LANE = ns.lane %}
{% set LANE_EXTRUDER = manager.lanes_by_fps[LANE].extruder %}
{% set STRICT = params.STRICT|default(0)|int == 1 %}
{% set STAGED = params.STAGED|default(0)|int == 1 %}
{% set UNLOAD_SPEED = v.unload_speed|default(1000) %}
{% if STRICT and pause_triggered %}
{ action_raise_error("Resolve the previous unload sensor failure before retrying") }
{% endif %}
{% if not printer[LANE_EXTRUDER].can_extrude or printer[LANE_EXTRUDER].temperature < v.minimum_extrude_temperature|default(0) %}
{ action_raise_error("Heat the extruder before unloading OpenAMS filament. Cutting and retracting need extrusion temperature") }
{% endif %}


{% if not STAGED %}
OAMSM_STAGE PLAN=cut,retract FPS={LANE}
{% endif %}

{% set PRE_HOMING_TARGET = printer[LANE_EXTRUDER].target|default(0) %}
{% if STRICT and printer.toolhead.homed_axes != 'xyz' %}
G28
_OAMS_AFTER_HOMING EXTRUDER={LANE_EXTRUDER} TARGET={PRE_HOMING_TARGET}
{% endif %}
SAVE_GCODE_STATE NAME=oams_unload
{% if not STRICT %}
SET_GCODE_VARIABLE MACRO=SAFE_UNLOAD_FILAMENT VARIABLE=pause_triggered VALUE=False
{% endif %}
M83
OAMSM_FOLLOWER ENABLE=1 DIRECTION=0 FPS={LANE}
SET_STEPPER_ENABLE STEPPER={LANE_EXTRUDER} ENABLE=1
OAMSM_STAGE NAME=cut FPS={LANE}
G1 E-{v.retract_length} F{UNLOAD_SPEED}
CUT_FILAMENT

M83
G1 E-{v.extrusion_unload_length} F{UNLOAD_SPEED}
M400
_UNLOAD_FS_OUT STRICT={1 if STRICT else 0} FPS={LANE}
_OAMS_FINISH_UNLOAD STRICT={1 if STRICT else 0} STARTED_PAUSED={1 if printer.pause_resume.is_paused else 0} STAGED={1 if STAGED else 0} FPS={LANE}

gcode_macro SEARCH_VARS.gcode:
{% set search = params.S|lower %}
{% set ns = namespace() %}
{% for item in printer %}
{% if ' ' in item %}
{% set ns.path = ['printer', "['%s']" % (item), ''] %}
{% else %}
{% set ns.path = ['printer.', item, ''] %}
{% endif %}

{% if search in ns.path|lower %}
{ action_respond_info(ns.path|join) }
{% endif %}

{% if printer[item].items() %}
{% for childkey, child in printer[item].items() recursive %}
{% set ns.path = ns.path[:loop.depth|int + 1] %}

{% if ' ' in childkey %}
{% set null = ns.path.append("['%s']" % (childkey)) %}
{% else %}
{% set null = ns.path.append(".%s" % (childkey)) %}
{% endif %}

{% if child is mapping %}
{ loop(child.items()) }
{% else %}
{% if search in ns.path|lower %}
{ action_respond_info("%s : %s" % (ns.path|join, child)) }
{% endif %}
{% endif %}
{% endfor %}
{% endif %}
{% endfor %}

gcode_macro _CONTACT_ACTIVATE.gcode:
{% set PROBE_TEMP = 150 %}
{% set ACTUAL_TEMP = printer.extruder.temperature %}

{% if ACTUAL_TEMP > (PROBE_TEMP + 1) %}
M118 Extruder temperature of {ACTUAL_TEMP}°C is too high, lowering to {PROBE_TEMP}°C
M109 S{ PROBE_TEMP }
{% endif %}

gcode_macro _HOME_X.gcode:
{% set RUN_CURRENT_X = printer.configfile.settings['tmc2209 stepper_x'].run_current|float %}
{% set RUN_CURRENT_Y = printer.configfile.settings['tmc2209 stepper_y'].run_current|float %}
{% set HOME_CURRENT = 0.7 %}
SET_TMC_CURRENT STEPPER=stepper_x CURRENT={HOME_CURRENT}
SET_TMC_CURRENT STEPPER=stepper_y CURRENT={HOME_CURRENT}

G28.1 X
G91
G1 X-10 F1200

G4 P2000
SET_TMC_CURRENT STEPPER=stepper_x CURRENT={RUN_CURRENT_X}
SET_TMC_CURRENT STEPPER=stepper_y CURRENT={RUN_CURRENT_Y}

gcode_macro _HOME_Y.gcode:
{% set RUN_CURRENT_X = printer.configfile.settings['tmc2209 stepper_x'].run_current|float %}
{% set RUN_CURRENT_Y = printer.configfile.settings['tmc2209 stepper_y'].run_current|float %}
{% set HOME_CURRENT = 0.7 %}
SET_TMC_CURRENT STEPPER=stepper_x CURRENT={HOME_CURRENT}
SET_TMC_CURRENT STEPPER=stepper_y CURRENT={HOME_CURRENT}

G4 P2000
G28.1 Y
G91
G1 Y-10 F1200

G4 P2000
SET_TMC_CURRENT STEPPER=stepper_x CURRENT={RUN_CURRENT_X}
SET_TMC_CURRENT STEPPER=stepper_y CURRENT={RUN_CURRENT_Y}

gcode_macro _LOAD_FS_IN.gcode:
{% set fs_extruder_in = printer["gcode_macro _oams_macro_variables"].fs_extruder_in %}
{% set LANE = params.FPS|default(none) %}

{% if fs_extruder_in and not printer['filament_switch_sensor extruder_in'].filament_detected %}
{% if params.STRICT|default(0)|int == 1 %}
OAMSM_STAGE FAILED=1 {('FPS=' ~ LANE) if LANE is not none else ''}
{ action_raise_error("Filament not detected at toolhead extruder inlet") }
{% endif %}
RESPOND TYPE=error MSG='Filament not detected at toolhead extruder inlet... pausing for user intervention'
SET_GCODE_VARIABLE MACRO=_TX VARIABLE=pause_triggered VALUE=True
{% elif fs_extruder_in and printer['filament_switch_sensor extruder_in'].filament_detected %}
RESPOND TYPE=command MSG='Filament detected at toolhead extruder inlet... continue loading'
{% endif %}

gcode_macro _LOAD_FS_OUT.gcode:
{% set fs_extruder_out = printer["gcode_macro _oams_macro_variables"].fs_extruder_out %}
{% set LANE = params.FPS|default(none) %}

{% if fs_extruder_out and not printer['filament_switch_sensor extruder_out'].filament_detected %}
{% if params.STRICT|default(0)|int == 1 %}
OAMSM_STAGE FAILED=1 {('FPS=' ~ LANE) if LANE is not none else ''}
{ action_raise_error("Filament not detected between extruder and hotend") }
{% endif %}
RESPOND TYPE=error MSG='Filament not detected between toolhead extruder and hotend... pausing for user intervention'
SET_GCODE_VARIABLE MACRO=_TX VARIABLE=pause_triggered VALUE=True
{% elif fs_extruder_out and printer['filament_switch_sensor extruder_out'].filament_detected %}
RESPOND TYPE=command MSG='Filament successfully loaded through extruder... continue'
{% endif %}

gcode_macro _OAMS_ABORT.gcode:
{% set LANE = params.FPS|default(none) %}
OAMSM_STAGE FAILED=1 {('FPS=' ~ LANE) if LANE is not none else ''}
OAMSM_FOLLOWER ENABLE=0 DIRECTION=0
{% if params.STRICT|default(0)|int != 1 %}
PAUSE
{% endif %}
_OAMS_RAISE MSG="{params.MSG}"

gcode_macro _OAMS_AFTER_HOMING.gcode:
{% set v = printer["gcode_macro _oams_macro_variables"] %}
{% set EXTRUDER = params.EXTRUDER %}
{% set TARGET = params.TARGET|default(0)|float %}
{% set MINIMUM = v.minimum_extrude_temperature|default(0)|float %}
{% set HOT = printer[EXTRUDER] %}


{% set RESTORE = TARGET > 0 and TARGET >= MINIMUM %}
{% if RESTORE and HOT.target|default(0)|float != TARGET %}
RESPOND TYPE=command MSG='Homing changed the extruder target. Restoring {TARGET}'
SET_HEATER_TEMPERATURE HEATER={EXTRUDER} TARGET={TARGET}
{% endif %}
{% if RESTORE %}


{% set WAIT_MINIMUM = [TARGET - 5, MINIMUM]|max %}
{% if HOT.temperature|default(0)|float < WAIT_MINIMUM %}
RESPOND TYPE=command MSG='Waiting for the extruder to reach {WAIT_MINIMUM}'
TEMPERATURE_WAIT SENSOR={EXTRUDER} MINIMUM={WAIT_MINIMUM}
{% endif %}
{% elif not HOT.can_extrude or HOT.temperature|default(0)|float < MINIMUM %}
{ action_raise_error("Homing cooled the extruder and there is no target to restore. Heat the extruder before unloading or changing OpenAMS filament. Cutting and retracting need extrusion temperature") }
{% endif %}

gcode_macro _OAMS_CONFIRM_UNLOADED.gcode:
{% set manager = printer['oams_manager'] %}
{% set LANE = params.FPS|default(none) %}
{% set STAGED = params.STAGED|default(0)|int %}
{% set NEW_PAUSE = printer.pause_resume.is_paused and not params.STARTED_PAUSED|default(0)|int %}
{% set MSG = 'OpenAMS unload stopped because the printer was paused' if NEW_PAUSE else 'OpenAMS did not finish unloading. Inspect the filament path before retrying' %}
RESTORE_GCODE_STATE NAME=oams_unload
{% set LOADED_GROUP = manager.lanes_by_fps[LANE].group if LANE is not none else manager.current_group %}
{% if LOADED_GROUP is not none or NEW_PAUSE %}
_OAMS_ABORT STRICT={params.STRICT|default(0)|int} MSG="{MSG}" {('FPS=' ~ LANE) if LANE is not none else ''}
{% elif not STAGED %}
OAMSM_STAGE DONE=1 {('FPS=' ~ LANE) if LANE is not none else ''}
{% endif %}

gcode_macro _OAMS_CONTINUE_AFTER_INLET.gcode:
{% set v = printer["gcode_macro _oams_macro_variables"] %}
{% set manager = printer['oams_manager'] %}
{% set LANE = params.FPS|default(none) %}
{% set LANE_EXTRUDER = manager.lanes_by_fps[LANE].extruder if LANE is not none else printer.toolhead.extruder %}
{% set RELOAD_LENGTH = v.extrusion_reload_length + v.retract_length + v.hotend_meltzone_compensation %}
{% set NEW_PAUSE = printer.pause_resume.is_paused and not params.STARTED_PAUSED|default(0)|int %}
{% set MSG = 'OpenAMS toolchange stopped because the printer was paused' if NEW_PAUSE else 'OpenAMS toolchange stopped at the toolhead inlet check' %}
{% if printer["gcode_macro _TX"].pause_triggered or NEW_PAUSE %}
_OAMS_FAIL_TOOLCHANGE STRICT={params.STRICT} MSG="{MSG}" {('FPS=' ~ LANE) if LANE is not none else ''}
{% else %}
{% if params.CLEAN|default(0)|int == 1 %}
CLEAN_NOZZLE
M400
{% endif %}
SET_STEPPER_ENABLE STEPPER={LANE_EXTRUDER} ENABLE=1
M83
G1 E{RELOAD_LENGTH} F{v.reload_speed}
M400
G4 P1000
_LOAD_FS_OUT STRICT={params.STRICT} {('FPS=' ~ LANE) if LANE is not none else ''}
_OAMS_FINISH_TOOLCHANGE STRICT={params.STRICT} STARTED_PAUSED={params.STARTED_PAUSED} {('FPS=' ~ LANE) if LANE is not none else ''}
{% endif %}

gcode_macro _OAMS_CONTINUE_AFTER_LOAD.gcode:
{% set manager = printer['oams_manager'] %}
{% set LANE = params.FPS|default(none) %}
{% set STRICT = params.STRICT|default(0)|int %}
{% set STARTED_PAUSED = params.STARTED_PAUSED|default(0)|int %}
{% set LOADED_GROUP = manager.lanes_by_fps[LANE].group if LANE is not none else manager.current_group %}
{% set LOADED_SLOT = manager.lanes_by_fps[LANE].current_slot if LANE is not none else none %}
{% set NEW_PAUSE = printer.pause_resume.is_paused and not STARTED_PAUSED %}
{% if NEW_PAUSE %}
_OAMS_FAIL_TOOLCHANGE STRICT={STRICT} MSG="OpenAMS toolchange stopped because the printer was paused" {('FPS=' ~ LANE) if LANE is not none else ''}
{% elif LOADED_GROUP != params.GROUP or (STRICT == 1 and LOADED_SLOT != params.SLOT|int) %}
_OAMS_FAIL_TOOLCHANGE STRICT={STRICT} MSG="OpenAMS did not load {params.GROUP}. The toolhead was not reloaded" {('FPS=' ~ LANE) if LANE is not none else ''}
{% else %}
_LOAD_FS_IN STRICT={STRICT} {('FPS=' ~ LANE) if LANE is not none else ''}
_OAMS_CONTINUE_AFTER_INLET STRICT={STRICT} STARTED_PAUSED={STARTED_PAUSED} CLEAN={params.CLEAN|default(0)|int} {('FPS=' ~ LANE) if LANE is not none else ''}
{% endif %}

gcode_macro _OAMS_CONTINUE_AFTER_UNLOAD.gcode:
{% set manager = printer['oams_manager'] %}
{% set LANE = params.FPS|default(none) %}
{% set NEW_PAUSE = printer.pause_resume.is_paused and not params.STARTED_PAUSED|default(0)|int %}
{% set MSG = 'OpenAMS toolchange stopped because the printer was paused' if NEW_PAUSE else 'OpenAMS toolchange stopped before loading. Inspect the filament path before retrying' %}
{% set ARGS = 'GROUP=' ~ params.GROUP ~ ' SLOT=' ~ params.SLOT ~ ' STRICT=' ~ params.STRICT ~ ' STARTED_PAUSED=' ~ params.STARTED_PAUSED ~ ((' FPS=' ~ LANE) if LANE is not none else '') %}
{% set LOADED_GROUP = manager.lanes_by_fps[LANE].group if LANE is not none else manager.current_group %}
{% if printer["gcode_macro _TX"].pause_triggered or NEW_PAUSE or LOADED_GROUP is not none %}
_OAMS_FAIL_TOOLCHANGE STRICT={params.STRICT} MSG="{MSG}" {('FPS=' ~ LANE) if LANE is not none else ''}
{% else %}
OAMSM_STAGE NAME=feed {('FPS=' ~ LANE) if LANE is not none else ''}
{% if params.STRICT|int == 1 %}
OAMSM_LOAD_FILAMENT GROUP={params.GROUP} SLOT={params.SLOT}
{% else %}
OAMSM_LOAD_FILAMENT GROUP={params.GROUP}
{% endif %}


M400
G4 P1000
_OAMS_CONTINUE_AFTER_LOAD {ARGS} CLEAN=1
{% endif %}

gcode_macro _OAMS_FAIL_TOOLCHANGE.gcode:
{% set LANE = params.FPS|default(none) %}
OAMSM_STAGE FAILED=1 {('FPS=' ~ LANE) if LANE is not none else ''}
RESTORE_GCODE_STATE NAME=oams_toolchange
_OAMS_ABORT STRICT={params.STRICT|default(0)} MSG="{params.MSG}" {('FPS=' ~ LANE) if LANE is not none else ''}

gcode_macro _OAMS_FINISH_TOOLCHANGE.gcode:
{% set LANE = params.FPS|default(none) %}
{% set NEW_PAUSE = printer.pause_resume.is_paused and not params.STARTED_PAUSED|default(0)|int %}
{% set MSG = 'OpenAMS toolchange stopped because the printer was paused' if NEW_PAUSE else 'OpenAMS toolchange stopped at the extruder outlet check' %}
{% if printer["gcode_macro _TX"].pause_triggered or NEW_PAUSE %}
_OAMS_FAIL_TOOLCHANGE STRICT={params.STRICT} MSG="{MSG}" {('FPS=' ~ LANE) if LANE is not none else ''}
{% else %}
OAMSM_STAGE DONE=1 {('FPS=' ~ LANE) if LANE is not none else ''}
RESTORE_GCODE_STATE NAME=oams_toolchange MOVE=1 MOVE_SPEED=100
{% endif %}

gcode_macro _OAMS_FINISH_UNLOAD.gcode:
{% set v = printer["gcode_macro _oams_macro_variables"] %}
{% set LANE = params.FPS|default(none) %}
{% set STRICT = params.STRICT|default(0)|int %}
{% set STAGED = params.STAGED|default(0)|int %}
{% set STARTED_PAUSED = params.STARTED_PAUSED|default(0)|int %}
{% set NEW_PAUSE = printer.pause_resume.is_paused and not STARTED_PAUSED %}
{% set MSG = 'OpenAMS unload stopped because the printer was paused' if NEW_PAUSE else 'OpenAMS unload stopped after the toolhead sensor check' %}
{% if not printer["gcode_macro SAFE_UNLOAD_FILAMENT"].pause_triggered and not NEW_PAUSE %}
G1 E-{v.extrusion_unload_additional_length|default(250)} F{v.additional_unload_speed|default(5000)}

G4 P1000
OAMSM_STAGE NAME=retract {('FPS=' ~ LANE) if LANE is not none else ''}
{% if STRICT == 1 %}
OAMSM_UNLOAD_FILAMENT STRICT=1 {('FPS=' ~ LANE) if LANE is not none else ''}
{% else %}
OAMSM_UNLOAD_FILAMENT {('FPS=' ~ LANE) if LANE is not none else ''}
{% endif %}
M400
_OAMS_CONFIRM_UNLOADED STRICT={STRICT} STARTED_PAUSED={STARTED_PAUSED} STAGED={STAGED} {('FPS=' ~ LANE) if LANE is not none else ''}
{% else %}
RESTORE_GCODE_STATE NAME=oams_unload
_OAMS_ABORT STRICT={STRICT} MSG="{MSG}" {('FPS=' ~ LANE) if LANE is not none else ''}
{% endif %}

gcode_macro _TOOLHEAD_PARK_PAUSE_CANCEL.gcode:
{% set macro_found = True if printer['gcode_macro _CLIENT_VARIABLE'] is defined else False %}
{% set client = printer['gcode_macro _CLIENT_VARIABLE'] %}
{% set velocity = printer.configfile.settings.pause_resume.recover_velocity %}
{% set use_custom     = False if not macro_found
else False if client.use_custom_pos is not defined
else True  if client.use_custom_pos|lower == 'true'
else False %}
{% set custom_park_x  = 0.0 if not macro_found else client.custom_park_x|default(0.0) %}
{% set custom_park_y  = 0.0 if not macro_found else client.custom_park_y|default(0.0) %}
{% set park_dz        = 2.0 if not macro_found else client.custom_park_dz|default(2.0)|abs %}
{% set use_fw_retract = False if not macro_found
else False if client.use_fw_retract is not defined
else True  if client.use_fw_retract|lower == 'true' and printer.firmware_retraction is defined
else False %}
{% set retract    = 1.0  if not macro_found else client.retract|default(1.0)|abs %}
{% set sp_retract = 2100 if not macro_found else client.speed_retract|default(35) * 60 %}
{% set sp_hop     = 900  if not macro_found else client.speed_hop|default(15) * 60 %}
{% set sp_move    = velocity * 60 if not macro_found else client.speed_move|default(velocity) * 60 %}

{% set act = printer.toolhead.position %}
{% set max = printer.toolhead.axis_maximum %}
{% set cone = printer.toolhead.cone_start_z|default(max.z) %}
{% set round_bed = True if printer.configfile.settings.printer.kinematics is in ['delta','polar','rotary_delta','winch']
else False %}

{% set z_min = params.Z_MIN|default(0)|float %}
{% set z_park = [[(act.z + park_dz), z_min]|max, max.z]|min %}
{% set x_park = params.X       if params.X is defined
else custom_park_x  if use_custom
else 0.0            if round_bed
else (max.x - 5.0) %}
{% set y_park = params.Y       if params.Y is defined
else custom_park_y  if use_custom
else (max.y - 5.0)  if round_bed and z_park < cone
else 0.0            if round_bed
else (max.y - 5.0) %}

{% if printer.extruder.can_extrude %}
{% if use_fw_retract %}
G10
{% else %}
M83
G1 E-{retract} F{sp_retract}
{% if printer.gcode_move.absolute_extrude %} M82 {% endif %}
{% endif %}
{% else %}
{action_respond_info("Extruder not hot enough")}
{% endif %}
{% if "xyz" in printer.toolhead.homed_axes %}
G90
G1 Z{z_park} F{sp_hop}
G1 X{x_park} Y{y_park} F{sp_move}
{% if not printer.gcode_move.absolute_coordinates %} G91 {% endif %}
{% else %}
{action_respond_info("Printer not homed")}
{% endif %}

gcode_macro _TX.gcode:
{% set v = printer["gcode_macro _oams_macro_variables"] %}
{% set manager = printer['oams_manager'] %}
{% set GROUP = params.GROUP %}
{% set LANE = (manager.topology.groups.get(GROUP) or {}).get('lane') %}
{% set TARGETED = 'SLOT' in params %}
{% set SLOT = params.SLOT|default(-1)|int %}
{% set LOADED_GROUP = manager.lanes_by_fps[LANE].group if LANE is not none else none %}
{% set LOADED_SLOT = manager.lanes_by_fps[LANE].current_slot if TARGETED and LANE is not none else none %}
{% set EXCLUDED = printer.exclude_object.current_object in printer.exclude_object.excluded_objects %}
{% set SWITCH = not EXCLUDED and not (LOADED_GROUP == GROUP and (not TARGETED or LOADED_SLOT == SLOT)) %}
{% set LOAD_ARGS = 'GROUP=' ~ GROUP ~ ((' SLOT=' ~ SLOT) if TARGETED else '') %}
{% set HELPER_ARGS = 'GROUP=' ~ GROUP ~ ' SLOT=' ~ SLOT ~ ' STRICT=' ~ (1 if TARGETED else 0) ~ ' STARTED_PAUSED=' ~ (1 if printer.pause_resume.is_paused else 0) ~ ((' FPS=' ~ LANE) if LANE is not none else '') %}
{% set LANE_EXTRUDER = manager.lanes_by_fps[LANE].extruder if LANE is not none else printer.toolhead.extruder %}



{% set HAS_GCO_ROUTINES = 'gco_routines' in printer and printer.configfile.settings.get('gcode_macro _tx', {}).get('render_mode', 'legacy') == 'ordered' %}
{% if TARGETED %}
{% if pause_triggered %}
{ action_raise_error("Resolve the previous load sensor failure before retrying") }
{% endif %}

OAMSM_VALIDATE_LOAD GROUP={GROUP} SLOT={params.SLOT}
{% endif %}
{% if SWITCH %}

{% if not TARGETED and ('filament_group ' ~ GROUP|lower) not in printer.configfile.settings %}
{ action_raise_error("Unknown OpenAMS filament group " ~ GROUP) }
{% endif %}

{% if not printer[LANE_EXTRUDER].can_extrude or printer[LANE_EXTRUDER].temperature < v.minimum_extrude_temperature|default(0) %}
{ action_raise_error("Heat the extruder before an OpenAMS toolchange. Cutting and reloading need extrusion temperature") }
{% endif %}


{% if LOADED_GROUP is not none %}
OAMSM_STAGE PLAN=cut,retract,feed {('FPS=' ~ LANE) if LANE is not none else ''}
{% else %}
OAMSM_STAGE PLAN=feed {('FPS=' ~ LANE) if LANE is not none else ''}
{% endif %}
{% endif %}







{% set PRE_HOMING_TARGET = printer[LANE_EXTRUDER].target|default(0) %}
{% if printer.toolhead.homed_axes != 'xyz' %}
RESPOND TYPE=command MSG='Homing'
G28
{% if SWITCH %}
_OAMS_AFTER_HOMING EXTRUDER={LANE_EXTRUDER} TARGET={PRE_HOMING_TARGET}
{% endif %}
{% endif %}
{% if not EXCLUDED %}
{% if not SWITCH %}
RESPOND TYPE=command MSG='Toolhead already loaded with {GROUP}'
{% else %}
RESPOND TYPE=command MSG='Switching {LOADED_GROUP} -> {GROUP}'
{% if not TARGETED %}
SET_GCODE_VARIABLE MACRO=_TX VARIABLE=pause_triggered VALUE=False
{% endif %}
SAVE_GCODE_STATE NAME=oams_toolchange
{% if LOADED_GROUP is not none %}
{% if TARGETED %}
SAFE_UNLOAD_FILAMENT STRICT=1 STAGED=1 FPS={LANE}
{% else %}
SAFE_UNLOAD_FILAMENT STAGED=1 FPS={LANE}
{% endif %}
{% endif %}

{% if HAS_GCO_ROUTINES and not printer.pause_resume.is_paused and not printer["gcode_macro _TX"].pause_triggered and (manager.lanes_by_fps[LANE].group if LANE is not none else manager.current_group) is none %}



OAMSM_STAGE NAME=feed {('FPS=' ~ LANE) if LANE is not none else ''}
START
OAMSM_LOAD_FILAMENT {LOAD_ARGS}
END
CLEAN_NOZZLE
M400
WAIT
_OAMS_CONTINUE_AFTER_LOAD {HELPER_ARGS}
{% else %}
_OAMS_CONTINUE_AFTER_UNLOAD {HELPER_ARGS}
{% endif %}
{% endif %}
{% endif %}

gcode_macro _UNLOAD_FS_OUT.gcode:
{% set fs_extruder_out = printer["gcode_macro _oams_macro_variables"].fs_extruder_out %}
{% set LANE = params.FPS|default(none) %}

{% if fs_extruder_out and printer['filament_switch_sensor extruder_out'].filament_detected %}
{% if params.STRICT|default(0)|int == 1 %}
OAMSM_STAGE FAILED=1 {('FPS=' ~ LANE) if LANE is not none else ''}
{ action_raise_error("Filament still detected between extruder and hotend after cutting") }
{% endif %}
RESPOND TYPE=error MSG='Filament detected between extruder and hotend!  This is most likely a failure to cut the filament, or the settings are incorrect and the extrusion_unload_length is insufficient to retract the remaining filament past the gears of the extruder   ... pausing for user intervention'
