gcode_macro _oams_after_homing.gcode:
{% set v = printer["gcode_macro _oams_macro_variables"] %}
{% set EXTRUDER = params.EXTRUDER %}
{% set TARGET = params.TARGET|default(0)|float %}
{% set MINIMUM = v.minimum_extrude_temperature|default(0)|float %}
{% set HOT = printer[EXTRUDER] %}


{% set RESTORE = TARGET > 0 and TARGET >= MINIMUM %}
{% if RESTORE and HOT.target|default(0)|float != TARGET %}
RESPOND TYPE=command MSG='Homing changed the extruder target. Restoring {TARGET}'
SET_HEATER_TEMPERATURE HEATER={EXTRUDER} TARGET={TARGET}
{% endif %}
{% if RESTORE %}


{% set WAIT_MINIMUM = [TARGET - 5, MINIMUM]|max %}
{% if HOT.temperature|default(0)|float < WAIT_MINIMUM %}
RESPOND TYPE=command MSG='Waiting for the extruder to reach {WAIT_MINIMUM}'
TEMPERATURE_WAIT SENSOR={EXTRUDER} MINIMUM={WAIT_MINIMUM}
{% endif %}
{% elif not HOT.can_extrude or HOT.temperature|default(0)|float < MINIMUM %}
{ action_raise_error("Homing cooled the extruder and there is no target to restore. Heat the extruder before unloading or changing OpenAMS filament. Cutting and retracting need extrusion temperature") }
{% endif %}

