RESTORE_GCODE_STATE NAME=oams_unload
{% set LOADED_GROUP = manager.lanes_by_fps[LANE].group if LANE is not none else manager.current_group %}
{% if LOADED_GROUP is not none or NEW_PAUSE %}
_OAMS_ABORT STRICT={params.STRICT|default(0)|int} MSG="{MSG}" {('FPS=' ~ LANE) if LANE is not none else ''}
