gcode_macro extrude_volumetric.gcode:
{% set D = params.D|float %}
{% set EXTRUDER = params.EXTRUDER|default("extruder") %}
{% set VOLUME = params.VOLUME|float %}
{% set SPEED = params.SPEED|float %}


{% if D <= 0 %}
respond_error "Invalid filament diameter: D must be greater than 0"
return
{% endif %}
{% if VOLUME <= 0 %}
respond_error "Invalid volume: VOLUME must be greater than 0"
return
{% endif %}
{% if SPEED <= 0 %}
respond_error "Invalid speed: SPEED must be greater than 0"
return
{% endif %}


{% set area = (3.14159 * (D / 2) ** 2) %}


{% set length = VOLUME / area %}


respond_info "Extruding length of filament: {length} mm at speed { SPEED } mm/min with filament diameter {D } mm"


ACTIVATE_EXTRUDER EXTRUDER={EXTRUDER}
G1 E{length} F{SPEED}

