{% if ns.lane is none %}{% for name in manager.lanes_by_fps %}{% if manager.lanes_by_fps[name].extruder == printer.toolhead.extruder %}{% set ns.lane = name %}{% endif %}{% endfor %}{% endif %}
{% if ns.lane is none and manager.lanes_by_fps|length == 1 %}{% set ns.lane = (manager.lanes_by_fps|list)[0] %}{% endif %}
